class Document(TLObject):
    """The TL type document#8fd4c4d8, a form of Document."""

    __slots__ = ("id", "access_hash", "file_reference", "date", "mime_type", "size", "thumbs", "video_thumbs", "dc_id", "attributes",)

    ID = 0x8FD4C4D8
    QUALNAME = "types.Document"

    def __init__(
        self,
        *,
        id: int,
        access_hash: int,
        file_reference: bytes,
        date: int,
        mime_type: str,
        size: int,
        thumbs: list[base.PhotoSize] | None = None,
        video_thumbs: list[base.VideoSize] | None = None,
        dc_id: int,
        attributes: list[base.DocumentAttribute],
    ) -> None:
        self.id = id
        self.access_hash = access_hash
        self.file_reference = file_reference
        self.date = date
        self.mime_type = mime_type
        self.size = size
        self.thumbs = thumbs
        self.video_thumbs = video_thumbs
        self.dc_id = dc_id
        self.attributes = attributes

    def write_body(self, w: TLWriter) -> None:
        flags = 0
        if self.thumbs is not None:
            flags |= 1 << 0
        if self.video_thumbs is not None:
            flags |= 1 << 1
        w.write_int(flags)
        w.write_long(self.id)
        w.write_long(self.access_hash)
        w.write_bytes(self.file_reference)
        w.write_int(self.date)
        w.write_string(self.mime_type)
        w.write_long(self.size)
        if self.thumbs is not None:
            w.write_vector(self.thumbs)
        if self.video_thumbs is not None:
            w.write_vector(self.video_thumbs)
        w.write_int(self.dc_id)
        w.write_vector(self.attributes)

    @classmethod
    def read(cls, r: TLReader) -> Self:
        flags = r.read_int()
        id = r.read_long()
        access_hash = r.read_long()
        file_reference = r.read_bytes()
        date = r.read_int()
        mime_type = r.read_string()
        size = r.read_long()
        thumbs = r.read_vector() if flags & (1 << 0) else None
        video_thumbs = r.read_vector() if flags & (1 << 1) else None
        dc_id = r.read_int()
        attributes = r.read_vector()
        self = cls.__new__(cls)
        self.id = id
        self.access_hash = access_hash
        self.file_reference = file_reference
        self.date = date
        self.mime_type = mime_type
        self.size = size
        self.thumbs = thumbs
        self.video_thumbs = video_thumbs
        self.dc_id = dc_id
        self.attributes = attributes
        return self


