class Game(TLObject):
    """The TL type game#bdf9653b, a form of Game."""

    __slots__ = ("id", "access_hash", "short_name", "title", "description", "photo", "document",)

    ID = 0xBDF9653B
    QUALNAME = "types.Game"

    def __init__(
        self,
        *,
        id: int,
        access_hash: int,
        short_name: str,
        title: str,
        description: str,
        photo: base.Photo,
        document: base.Document | None = None,
    ) -> None:
        self.id = id
        self.access_hash = access_hash
        self.short_name = short_name
        self.title = title
        self.description = description
        self.photo = photo
        self.document = document

    def write_body(self, w: TLWriter) -> None:
        flags = 0
        if self.document is not None:
            flags |= 1 << 0
        w.write_int(flags)
        w.write_long(self.id)
        w.write_long(self.access_hash)
        w.write_string(self.short_name)
        w.write_string(self.title)
        w.write_string(self.description)
        self.photo.write(w)
        if self.document is not None:
            self.document.write(w)

    @classmethod
    def read(cls, r: TLReader) -> Self:
        flags = r.read_int()
        id = r.read_long()
        access_hash = r.read_long()
        short_name = r.read_string()
        title = r.read_string()
        description = r.read_string()
        photo = r.read_object()
        document = r.read_object() if flags & (1 << 0) else None
        self = cls.__new__(cls)
        self.id = id
        self.access_hash = access_hash
        self.short_name = short_name
        self.title = title
        self.description = description
        self.photo = photo
        self.document = document
        return self


