    __slots__ = ("test", "name_requested", "phone_requested", "email_requested", "shipping_address_requested", "flexible", "phone_to_provider", "email_to_provider", "recurring", "currency", "prices", "max_tip_amount", "suggested_tip_amounts", "terms_url", "subscription_period",)

    ID = 0x049EE584
    QUALNAME = "types.Invoice"

    def __init__(
        self,
        *,
        test: bool = False,
        name_requested: bool = False,
        phone_requested: bool = False,
        email_requested: bool = False,
        shipping_address_requested: bool = False,
        flexible: bool = False,
        phone_to_provider: bool = False,
        email_to_provider: bool = False,
        recurring: bool = False,
        currency: str,
        prices: list[base.LabeledPrice],
        max_tip_amount: int | None = None,
        suggested_tip_amounts: list[int] | None = None,
        terms_url: str | None = None,
        subscription_period: int | None = None,
    ) -> None:
        self.test = test
        self.name_requested = name_requested
        self.phone_requested = phone_requested
        self.email_requested = email_requested
        self.shipping_address_requested = shipping_address_requested
        self.flexible = flexible
        self.phone_to_provider = phone_to_provider
        self.email_to_provider = email_to_provider
        self.recurring = recurring
        self.currency = currency
        self.prices = prices
        self.max_tip_amount = max_tip_amount
        self.suggested_tip_amounts = suggested_tip_amounts
        self.terms_url = terms_url
        self.subscription_period = subscription_period

    def write_body(self, w: TLWriter) -> None:
        flags = 0
        if self.test:
            flags |= 1 << 0
        if self.name_requested:
            flags |= 1 << 1
        if self.phone_requested:
            flags |= 1 << 2
        if self.email_requested:
            flags |= 1 << 3
        if self.shipping_address_requested:
            flags |= 1 << 4
        if self.flexible:
            flags |= 1 << 5
        if self.phone_to_provider:
            flags |= 1 << 6
        if self.email_to_provider:
            flags |= 1 << 7
        if self.recurring:
            flags |= 1 << 9
        if self.max_tip_amount is not None:
            flags |= 1 << 8
        if self.suggested_tip_amounts is not None:
            flags |= 1 << 8
        if self.terms_url is not None:
            flags |= 1 << 10
        if self.subscription_period is not None:
            flags |= 1 << 11
        w.write_int(flags)
        w.write_string(self.currency)
        w.write_vector(self.prices)
        if self.max_tip_amount is not None:
            w.write_long(self.max_tip_amount)
        if self.suggested_tip_amounts is not None:
            w.write_vector(self.suggested_tip_amounts, TLWriter.write_long)
        if self.terms_url is not None:
            w.write_string(self.terms_url)
        if self.subscription_period is not None:
            w.write_int(self.subscription_period)

    @classmethod
    def read(cls, r: TLReader) -> Self:
        flags = r.read_int()
        test = bool(flags & (1 << 0))
        name_requested = bool(flags & (1 << 1))
        phone_requested = bool(flags & (1 << 2))
        email_requested = bool(flags & (1 << 3))
        shipping_address_requested = bool(flags & (1 << 4))
        flexible = bool(flags & (1 << 5))
        phone_to_provider = bool(flags & (1 << 6))
        email_to_provider = bool(flags & (1 << 7))
        recurring = bool(flags & (1 << 9))
        currency = r.read_string()
        prices = r.read_vector()
        max_tip_amount = r.read_long() if flags & (1 << 8) else None
        suggested_tip_amounts = r.read_vector(TLReader.read_long) if flags & (1 << 8) else None
        terms_url = r.read_string() if flags & (1 << 10) else None
        subscription_period = r.read_int() if flags & (1 << 11) else None
        self = cls.__new__(cls)
        self.test = test
        self.name_requested = name_requested
        self.phone_requested = phone_requested
        self.email_requested = email_requested
        self.shipping_address_requested = shipping_address_requested
